/bin/bash -lc 'set -o pipefail; p_tmp=$(mktemp -d "$TMPDIR/ishagarh-courses.XXXXXX"); curl --insecure -fsSL --max-time 45 -A '"'Mozilla/5.0' 'https://highereducation.mp.gov.in/?page=mrINnUA5p3mBGhZTlOZW%2BA%3D%3D&orgid=35' -o \""'$p_tmp/courses.html"; python3 -c '"'from bs4 import BeautifulSoup; import sys; s=BeautifulSoup(open(sys.argv[1],encoding=\"utf-8\"),\"html.parser\");
for i,t in enumerate(s.find_all(\"table\")):
 print(\"TABLE\",i); 
 for tr in t.find_all(\"tr\"): print(\" | \".join(\" \".join(x.get_text(\" \",strip=True).split()) for x in tr.find_all([\"th\",\"td\"])))' \""'$p_tmp/courses.html"'

