/bin/bash -lc 'task_tmp="$(find "$TMPDIR" -maxdepth 1 -type d -name '"'govcollege-ishagarh.*' | sort | tail -n 1)\"
course_file=\""'$(rg -l '"'Programmes Offered' \""'$task_tmp"/page_*.html | head -n 1)"
perl -0777 -ne '"'
  while (/<tr>(.*?)<\\/tr>/sg) {
    my "'$row=$1;
    my @cells = ($row =~ /<td[''^>]*>(.*?)<'"\\/td>/sg);
    next unless @cells;
    for (@cells) { s/<["'^>]+>/ /g; s/&nbsp;/ /g; s/'"\\s+/ /g; s/"'^'"\\s+|\\s+"'$//g; }
    print join(" | ", @cells), "'"\\n\";
  }
' \""'$course_file" | sed -n '"'1,120p'"

